"""Bounded private scratch storage for contexts generated by this process.

No public reader accepts these files. Reports never contain pickle or a scratch
path. The private directory, digest and in-memory index are required for reads.
"""
from __future__ import annotations

from dataclasses import dataclass
import gzip
import hashlib
import os
from pathlib import Path
import pickle
import tempfile

from scar.analysis.program_lowering import PreparedSource, _symbol_tables
from scar.ir.program.expansion import ContextStoreBudget


class ContextStoreLimit(ValueError):
    pass


@dataclass(frozen=True)
class _Stored:
    file: Path
    sha256: str
    raw_bytes: int
    source_fingerprint: str
    root: Path


class _CompressedWriter:
    def __init__(self, store, stream):
        self.store, self.stream = store, stream

    def write(self, data):
        if len(data) > self.store.budget.max_compressed_bytes - self.store.compressed_bytes_written:
            raise ContextStoreLimit("compressed context store budget exhausted")
        count = self.stream.write(data)
        self.store.compressed_bytes_written += count
        return count

    def flush(self):
        self.stream.flush()


class _RecordWriter:
    def __init__(self, store, stream):
        self.store, self.stream, self.written = store, stream, 0

    def write(self, data):
        if len(data) > self.store.budget.max_record_bytes - self.written:
            raise ContextStoreLimit("uncompressed context record budget exhausted")
        count = self.stream.write(data)
        self.written += count
        self.store.uncompressed_bytes_written += count
        return count


class PreparedContextStore:
    def __init__(self, budget=ContextStoreBudget()):
        if type(budget) is not ContextStoreBudget:
            raise TypeError("context store requires a ContextStoreBudget")
        budget.__post_init__()
        self.budget = budget
        self._temporary = tempfile.TemporaryDirectory(prefix="scar-context-")
        self.directory = Path(self._temporary.name)
        self.directory.chmod(0o700)
        self.compressed_bytes_written = self.uncompressed_bytes_written = 0
        self.restore_attempts = self.compressed_payload_bytes_restored = 0
        self._stored = {}

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        self._stored.clear()
        self._temporary.cleanup()

    def put(self, context):
        key = str(context.path)
        if key in self._stored:
            raise ValueError("context already stored")
        path = self.directory / (hashlib.sha256(key.encode()).hexdigest() + ".gz")
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            with os.fdopen(descriptor, "wb") as stream:
                compressed = _CompressedWriter(self, stream)
                with gzip.GzipFile(filename="", fileobj=compressed, mode="wb", compresslevel=1, mtime=0) as archive:
                    writer = _RecordWriter(self, archive)
                    # symtable's native objects are reconstructed from sealed text.
                    payload = (context.path, context.root, context.text, context.semantic,
                               context.semantics, context.control, context.tree)
                    pickle.dump(payload, writer, protocol=5)
            self._stored[key] = _Stored(path, self._hash(path), writer.written,
                context.semantics.sources[key].fingerprint, context.root)
        except BaseException:
            path.unlink(missing_ok=True)
            raise

    @staticmethod
    def _hash(path):
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            while block := stream.read(1_048_576):
                digest.update(block)
        return digest.hexdigest()

    def get(self, path):
        self.restore_attempts += 1
        key = str(path)
        receipt = self._stored[key]
        if receipt.file.is_symlink() or self._hash(receipt.file) != receipt.sha256:
            raise ValueError("private context digest mismatch")
        self.compressed_payload_bytes_restored += receipt.file.stat().st_size
        with gzip.open(receipt.file, "rb") as stream:
            # Streaming dump was bounded before each write; the digest binds its
            # own output, so this read cannot exceed a new untrusted record cap.
            values = pickle.load(stream)
            if stream.read(1):
                raise ValueError("private context has trailing data")
        source_path, root, text, semantic, semantics, control, tree = values
        fingerprint = "sha256:" + hashlib.sha256(text.encode()).hexdigest()
        if (str(source_path) != key or root != receipt.root or fingerprint != receipt.source_fingerprint
                or semantics.sources[key].fingerprint != fingerprint):
            raise ValueError("private context source snapshot mismatch")
        return PreparedSource(source_path, root, text, semantic, semantics, control,
                              tree, _symbol_tables(text, source_path))
